insert into public.bfc_companies (id,title,sort_order,categories,phase_label,paragraphs,status,reference_links) select id,title,sort_order,categories,phase_label,paragraphs,status,reference_links from jsonb_populate_recordset(null::public.bfc_companies, '[{"id": "jim-dandys-transmissions", "title": "Jim Dandy’s Transmissions", "sort_order": 0, "categories": ["companies"], "phase_label": "BEFORE BRICKTOWN", "paragraphs": ["A business story that began with hard work.", "Before the downtown buildings and festival crowds, Jim ran Jim Dandy’s Transmissions. A 2020 Oklahoma Gazette account names the transmission business among his early ventures, alongside four nightclubs in the 1970s. It is an early chapter in the entrepreneurial path that eventually led to Bricktown. [4]"], "status": "published", "reference_links": [{"label": "[4]", "href": "#source-4"}]}, {"id": "super-rig-club", "title": "Super Rig Club", "sort_order": 1, "categories": ["companies"], "phase_label": "BEFORE BRICKTOWN · DATES APPROXIMATE", "paragraphs": ["The Superrig. A doorway into nightlife.", "The family’s chronology of Lackmeyer’s early-career profile recalls Jim backing an acquaintance’s nightclub, then taking over its operation. He discovered he enjoyed the business and welcomed guests at the door—a chapter that helped lead toward his later entertainment ventures. [18]", "Also remembered as “The Superrig.” Exact opening and closing dates remain to be established."], "status": "published", "reference_links": [{"label": "[18]", "href": "#source-18"}]}, {"id": "brewer-enterprises", "title": "Brewer Enterprises", "sort_order": 2, "categories": ["companies"], "phase_label": "THE FAMILY BUSINESS", "paragraphs": ["Another name behind the Bricktown years.", "Oklahoma Gazette’s November 2008 remembrance identifies Jim as the owner of both Brewer Enterprises and Brewer Entertainment. Brewer Enterprises deserves its own place in the family history; the report does not establish its founding date or a separate inventory of its assets. [6]"], "status": "published", "reference_links": [{"label": "[6]", "href": "#source-6"}]}, {"id": "bricktown-real-estate", "title": "Bricktown Real Estate", "sort_order": 3, "categories": ["companies"], "phase_label": "PROPERTY & DEVELOPMENT", "paragraphs": ["The buildings behind the possibilities.", "Downtown OKC’s board directory lists Brent Brewer with Bricktown Real Estate LLC. An earlier Greater Oklahoma City Chamber report identifies Bricktown Real Estate as the Santa Fe Depot’s owner and Brent as its president. Together, those records document another company in the family’s downtown story. [15] [16]"], "status": "published", "reference_links": [{"label": "[15]", "href": "#source-15"}, {"label": "[16]", "href": "#source-16"}]}, {"id": "bricktown-live", "title": "Bricktown Live", "sort_order": 4, "categories": ["companies", "places"], "phase_label": "THE ENTERTAINMENT YEARS", "paragraphs": ["A venue with a chapter of its own.", "The Journal Record’s 2008 remembrance lists Bricktown Live among the properties purchased and managed by Brewer Entertainment. Oklahoma Gazette also names it among the venues operated by Jim’s businesses. These are historical accounts; the exact opening and closing dates remain to be established. [5] [6]"], "status": "published", "reference_links": [{"label": "[5]", "href": "#source-5"}, {"label": "[6]", "href": "#source-6"}]}, {"id": "bricktown-ballroom", "title": "Bricktown Ballroom", "sort_order": 5, "categories": ["companies", "places"], "phase_label": "THE ENTERTAINMENT YEARS", "paragraphs": ["Another place to bring people together.", "Bricktown Ballroom appears in both The Journal Record and Oklahoma Gazette’s 2008 accounts of the Brewer venue portfolio. It belongs alongside Bricktown Live and the event center in the entertainment history. These sources establish the Brewer connection, while its full operating timeline remains to be documented. [5] [6]"], "status": "published", "reference_links": [{"label": "[5]", "href": "#source-5"}, {"label": "[6]", "href": "#source-6"}]}, {"id": "bricktown-haunted-warehouse", "title": "Bricktown Haunted Warehouse", "sort_order": 6, "categories": ["companies", "places"], "phase_label": "1986", "paragraphs": ["The attraction that helped start it all.", "The Haunted Warehouse gave people a reason to visit Bricktown before the canal and ballpark. Retro Metro OKC traces its origins to Jim Brewer and Craig Brown seeing possibilities in the old Hunzicker Lighting building. A 2013 Brewer Entertainment release documents its later home at the Chevy Bricktown Events Center. [1] [3] [11]"], "status": "published", "reference_links": [{"label": "[1]", "href": "#source-1"}, {"label": "[3]", "href": "#source-3"}, {"label": "[11]", "href": "#source-11"}]}, {"id": "obriens-bricktown-club", "title": "O’Brien’s Bricktown Club", "sort_order": 7, "categories": ["companies", "places"], "phase_label": "1990", "paragraphs": ["An Irish pub. A new Bricktown tradition.", "In a 2020 interview, Brent Brewer recalled opening O’Brien’s on March 17, 1990, alongside the St. Patrick’s Day parade and a block party in the parking lot. He said the pub operated for seven years. The celebration outlived the venue and became part of the family’s continuing story. [4]", "Family history: O’Brien’s was the first bar Jim opened in Bricktown, known for dueling pianos and karaoke. Because September was slow downtown, Jim took the karaoke to the State Fair of Oklahoma. O’Brien’s at the Fair ran for more than 20 years, and the family remembers it as the biggest party tent at the fair."], "status": "published", "reference_links": [{"label": "[4]", "href": "#source-4"}]}, {"id": "brewer-entertainment", "title": "Brewer Entertainment", "sort_order": 8, "categories": ["companies"], "phase_label": "1991", "paragraphs": ["Turning places into experiences.", "The Journal Record’s 2008 remembrance dates Brewer Entertainment Inc.’s start to 1991. At that time, it described a portfolio that included the Coca-Cola Bricktown Events Center, Bricktown Live, Bricktown Ballroom, and the Santa Fe train depot, alongside outdoor festivals. [5]"], "status": "published", "reference_links": [{"label": "[5]", "href": "#source-5"}]}, {"id": "bricktown-parking", "title": "Bricktown Parking", "sort_order": 9, "categories": ["companies"], "phase_label": "FAMILY BUSINESS", "paragraphs": ["The practical side of welcoming a crowd.", "Bricktown Parking belongs in the company history identified by the Brewer family. Public records also show why parking mattered to the district’s growth: the city’s 2008 parking strategy lists Jim Brewer among consulted stakeholders and Bricktown Parking Investors among contacted operators. [13]", "The company’s founding date and the relationship between the differently named parking entities remain to be documented."], "status": "published", "reference_links": [{"label": "[13]", "href": "#source-13"}]}, {"id": "fourth-of-july-festivals", "title": "Fourth of July festivals", "sort_order": 10, "categories": ["festivals"], "phase_label": "SUMMER TRADITION", "paragraphs": ["Fireworks, music, and a city coming together.", "A 2008 Oklahoma Gazette remembrance recounts the crowds at Bricktown’s 1999 Fourth of July fireworks after the canal opened. In 2007, the Gazette separately documented Brewer Entertainment’s Red, White and Boom! on the River—a free, three-day celebration at Downtown Airpark with the Oklahoma City Philharmonic and other performers. [6] [7]"], "status": "published", "reference_links": [{"label": "[6]", "href": "#source-6"}, {"label": "[7]", "href": "#source-7"}]}, {"id": "bricktown-blues-fest", "title": "Bricktown Blues Fest", "sort_order": 11, "categories": ["festivals"], "phase_label": "BLUES & BBQ", "paragraphs": ["A soundtrack for summer in Bricktown.", "The 2008 Gazette preview documents a two-day, free Blues & BBQ festival at Sheridan and Oklahoma avenues, with Marcia Ball, Bugs Henderson, and regional musicians. The family identifies Blues Fest as part of its history; the public account establishes the festival and lineup. [8]", "An original program or company archive will help document the first year and full production credits."], "status": "published", "reference_links": [{"label": "[8]", "href": "#source-8"}]}, {"id": "bricktown-reggae-fest", "title": "Bricktown Reggae Fest", "sort_order": 12, "categories": ["festivals"], "phase_label": "REGGAE & COMMUNITY", "paragraphs": ["A different rhythm for downtown.", "The Journal Record reported in July 2014 that Brewer Entertainment had hosted Reggae Fest for 19 years. Its account describes a free event with performers including Watusi, Ugly Lion, and The Effinays, and an emphasis on bringing live entertainment to Bricktown. [9]"], "status": "published", "reference_links": [{"label": "[9]", "href": "#source-9"}]}, {"id": "coca-cola-chevy-bricktown-events-center", "title": "Coca-Cola & Chevy Bricktown Events Center", "sort_order": 13, "categories": ["companies", "places"], "phase_label": "THE EVENT-CENTER YEARS", "paragraphs": ["Two names in one venue’s story.", "A 2008 account places the Coca-Cola venue within Brewer Entertainment’s operations. Songkick identifies Chevy Bricktown Event Center as formerly the Coca-Cola Bricktown Event Center. Brewer Entertainment’s 2013 announcement documents the Chevy name and a Haunted Warehouse season at the venue. [5] [10] [11]", "The precise sponsorship-change date is still to be established."], "status": "published", "reference_links": [{"label": "[5]", "href": "#source-5"}, {"label": "[10]", "href": "#source-10"}, {"label": "[11]", "href": "#source-11"}]}, {"id": "santa-fe-depot", "title": "Santa Fe Depot", "sort_order": 14, "categories": ["companies", "places"], "phase_label": "1998", "paragraphs": ["Preserving a gateway to Oklahoma City.", "Amtrak’s station history records Jim Brewer’s 1998 purchase of the depot and the renovation that followed. The Heartland Flyer began service in 1999. This chapter connects the family’s downtown work with the return of passenger rail to Oklahoma. [12]"], "status": "published", "reference_links": [{"label": "[12]", "href": "#source-12"}]}, {"id": "the-bricktown-okctopus", "title": "The Bricktown Okctopus", "sort_order": 15, "categories": ["places"], "phase_label": "2016", "paragraphs": ["A new landmark on a familiar wall.", "Oklahoma Tourism records Jack Fowler’s mural on the north side of the Chevy Bricktown Events Center in late 2016. The 200-foot-wide artwork made the building part of Bricktown’s public-art landscape. [14]"], "status": "published", "reference_links": [{"label": "[14]", "href": "#source-14"}]}]'::jsonb) on conflict (id) do nothing;
insert into public.bfc_timeline (id,title,date_label,sort_order,era,paragraphs,evidence_note,full_width,status,reference_links) select id,title,date_label,sort_order,era,paragraphs,evidence_note,full_width,status,reference_links from jsonb_populate_recordset(null::public.bfc_timeline, '[{"id": "where-it-all-began", "title": "Where it all began", "date_label": "1937", "sort_order": 0, "era": "BEFORE BRICKTOWN", "paragraphs": ["Jim D. Brewer is born February 6. His mother, Evelyn, raises him and his four sisters in southeast Oklahoma City by ironing clothes and sewing quilts. Jim is mowing lawns and doing odd jobs while still in grade school. [17]"], "evidence_note": "Early-life detail from family-supplied chronology; dates approximate", "full_width": false, "status": "published", "reference_links": [{"label": "[17]", "href": "#source-17"}]}, {"id": "out-on-his-own-at-11", "title": "Out on his own at 11", "date_label": "c. 1948", "sort_order": 1, "era": "BEFORE BRICKTOWN", "paragraphs": ["Jim leaves home to live with his grandfather near SE 28 and Central. He works until midnight at the Play More Bowling Alley at NW 4 and Broadway, walks miles home, and sleeps in the chicken coop so he doesn''t break his grandfather''s 5 a.m. breakfast rule. [17]"], "evidence_note": "Early-life detail from family-supplied chronology; dates approximate", "full_width": false, "status": "published", "reference_links": [{"label": "[17]", "href": "#source-17"}]}, {"id": "jim-dandy-s-transmissions", "title": "Jim Dandy''s Transmissions", "date_label": "1950s–60s", "sort_order": 2, "era": "BEFORE BRICKTOWN", "paragraphs": ["Working at an uncle''s salvage yard, Jim learns to rebuild transmissions. After marrying and starting a family, he opens his own shop, Jim Dandy''s Transmissions, on Reno near Harvey. [18]"], "evidence_note": "Early-life detail from family-supplied chronology; dates approximate", "full_width": false, "status": "published", "reference_links": [{"label": "[18]", "href": "#source-18"}]}, {"id": "the-superrig", "title": "The Superrig", "date_label": "1960s–70s", "sort_order": 3, "era": "BEFORE BRICKTOWN", "paragraphs": ["Jim backs an acquaintance who wants to buy a nightclub, then takes it over when his partner can''t run it. He finds he loves the business and greets every guest at the door. [18]"], "evidence_note": "Early-life detail from family-supplied chronology; dates approximate", "full_width": false, "status": "published", "reference_links": [{"label": "[18]", "href": "#source-18"}]}, {"id": "striking-oil", "title": "Striking oil", "date_label": "Late 1970s", "sort_order": 4, "era": "BEFORE BRICKTOWN", "paragraphs": ["Like much of Oklahoma during the boom, Jim buys an oil well. The first is a bust, but the second does very well. [18]"], "evidence_note": "Early-life detail from family-supplied chronology; dates approximate", "full_width": false, "status": "published", "reference_links": [{"label": "[18]", "href": "#source-18"}]}, {"id": "the-tom-cat-well", "title": "The Tom Cat well", "date_label": "Early 1980s", "sort_order": 5, "era": "BEFORE BRICKTOWN", "paragraphs": ["Jim’s recollection describes the Tom Cat well in western Oklahoma bringing in $600,000 in a single day. He leaves the nightclub life, sells his oil interests near the peak, and buys workover rigs, staying profitable through the subsequent oil downturn. [18]"], "evidence_note": "Early-life detail from family-supplied chronology; dates approximate", "full_width": false, "status": "published", "reference_links": [{"label": "[18]", "href": "#source-18"}]}, {"id": "called-to-bricktown", "title": "Called to Bricktown", "date_label": "Mid-1980s", "sort_order": 6, "era": "BEFORE BRICKTOWN", "paragraphs": ["Looking for someone to carry on founding developer Neal Horton''s work, his partner Williams turns to Jim for his cash and toughness. Jim starts buying warehouses from banks eager to sell. [19]"], "evidence_note": "Early-life detail from family-supplied chronology; dates approximate", "full_width": true, "status": "published", "reference_links": [{"label": "[19]", "href": "#source-19"}]}, {"id": "a-warehouse-becomes-a-destination", "title": "A warehouse becomes a destination", "date_label": "1986", "sort_order": 7, "era": "A DISTRICT COMES ALIVE", "paragraphs": ["Jim and Craig Brown see an opportunity in an old warehouse. The Bricktown Haunted Warehouse opens, giving people a reason to visit a district still finding its new identity. [1] [3]"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[1]", "href": "#source-1"}, {"label": "[3]", "href": "#source-3"}]}, {"id": "restaurants-bring-new-momentum", "title": "Restaurants bring new momentum", "date_label": "1989", "sort_order": 8, "era": "A DISTRICT COMES ALIVE", "paragraphs": ["Spaghetti Warehouse opens. Its crowds help establish demand for dining and entertainment among Bricktown’s old buildings. [3]"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[3]", "href": "#source-3"}]}, {"id": "obriens-st-patricks-day", "title": "O’Brien’s & St. Patrick’s Day", "date_label": "1990", "sort_order": 9, "era": "A DISTRICT COMES ALIVE", "paragraphs": ["Brent recalls opening O’Brien’s on March 17 alongside the parade and the first parking-lot block party. The pub and the celebration become part of the family story. [4]", "Family recollection: Patsy sold T-shirts at O’Brien’s."], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[4]", "href": "#source-4"}]}, {"id": "brewer-entertainment-takes-shape", "title": "Brewer Entertainment takes shape", "date_label": "1991", "sort_order": 10, "era": "A DISTRICT COMES ALIVE", "paragraphs": ["Jim starts Brewer Entertainment Inc., bringing venues and outdoor festivals into a growing entertainment business. [5]"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[5]", "href": "#source-5"}]}, {"id": "planning-the-canal-together", "title": "Planning the canal together", "date_label": "1997", "sort_order": 11, "era": "A DISTRICT COMES ALIVE", "paragraphs": ["Lackmeyer and Jack Money report on the public-private partnership behind the MAPS canal project, including Jim’s involvement as a Bricktown property owner. The Oklahoman ↗"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "The Oklahoman ↗", "href": "https://www.oklahoman.com/story/news/1997/02/17/maps-canal-project-relies-on-partnership/62323616007/"}]}, {"id": "a-new-chapter-for-the-depot", "title": "A new chapter for the depot", "date_label": "1998", "sort_order": 12, "era": "A DISTRICT COMES ALIVE", "paragraphs": ["Jim purchases the Santa Fe Depot. Restoration helps prepare the historic station for the return of passenger rail. [12]"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[12]", "href": "#source-12"}]}, {"id": "the-canal-opens-the-crowds-arrive", "title": "The canal opens. The crowds arrive.", "date_label": "1999", "sort_order": 13, "era": "A DISTRICT COMES ALIVE", "paragraphs": ["The Bricktown Canal opens in July, and the Heartland Flyer brings passenger service back to the depot. Recollections of the Fourth of July describe more than 50,000 people gathering for fireworks. [12] [6]"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[12]", "href": "#source-12"}, {"label": "[6]", "href": "#source-6"}]}, {"id": "red-white-and-boom-on-the-river", "title": "Red, White and Boom! on the River", "date_label": "2007", "sort_order": 14, "era": "A DISTRICT COMES ALIVE", "paragraphs": ["Brewer Entertainment promotes a free, three-day Fourth of July celebration at Downtown Airpark, with the Oklahoma City Philharmonic and other performers. Contemporary coverage previews the planned event. Oklahoma Gazette ↗"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "Oklahoma Gazette ↗", "href": "https://www.okgazette.com/news/celebrate-the-fourth-at-red-white-and-boom-festival-2947363/"}]}, {"id": "a-summer-soundtrack", "title": "A summer soundtrack", "date_label": "2008", "sort_order": 15, "era": "A DISTRICT COMES ALIVE", "paragraphs": ["Contemporary festival coverage previews Bricktown Blues & BBQ, with Marcia Ball, Bugs Henderson, and regional musicians. Live music remains part of the district’s summer identity. [8]"], "evidence_note": "Published sources and identified family recollections", "full_width": true, "status": "published", "reference_links": [{"label": "[8]", "href": "#source-8"}]}, {"id": "jim-tells-the-rest-of-his-story", "title": "Jim tells the rest of his story", "date_label": "2008", "sort_order": 16, "era": "JIM’S STORY, IN HIS LIFETIME", "paragraphs": ["The Oklahoman’s June video profile and Lackmeyer’s June 29 articles explore Jim’s early life, career, and the different views of his role in Bricktown. The Oklahoman Video Archive ↗ The Oklahoman ↗"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "The Oklahoman Video Archive ↗", "href": "https://www.youtube.com/watch?v=AZzUzYEXEl0"}, {"label": "The Oklahoman ↗", "href": "https://www.oklahoman.com/story/business/2008/06/29/hes-bricktowns-backbone-to-many-but-some-people-have-mixed-feelingsbrspan-classhl2strong-brew-span/61574240007/"}]}, {"id": "remembering-jim", "title": "Remembering Jim", "date_label": "2008", "sort_order": 17, "era": "JIM’S STORY, IN HIS LIFETIME", "paragraphs": ["Jim dies on November 11. Family remembrance and local reporting reflect on his life, his businesses, and his role in Bricktown’s renewal. [2] [5]"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[2]", "href": "#source-2"}, {"label": "[5]", "href": "#source-5"}]}, {"id": "a-place-in-the-walk-of-fame", "title": "A place in the Walk of Fame", "date_label": "2009", "sort_order": 18, "era": "THE FAMILY CARRIES IT FORWARD", "paragraphs": ["Lackmeyer reports on Walk of Fame recognition for Bricktown’s early developers, including Jim. The district’s public record begins a new chapter of remembrance. The Oklahoman ↗"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "The Oklahoman ↗", "href": "https://www.oklahoman.com/story/business/2009/07/03/bricktown-developers-honored-with-spots-on-walk-of-fame/61390863007/"}]}, {"id": "the-haunted-warehouse-at-chevy", "title": "The Haunted Warehouse at Chevy", "date_label": "2013", "sort_order": 19, "era": "THE FAMILY CARRIES IT FORWARD", "paragraphs": ["A Brewer Entertainment announcement documents the attraction’s 28th annual season at the Chevy Bricktown Events Center on California Avenue. [11]"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[11]", "href": "#source-11"}]}, {"id": "another-chapter-for-the-event-center", "title": "Another chapter for the event center", "date_label": "2014", "sort_order": 20, "era": "THE FAMILY CARRIES IT FORWARD", "paragraphs": ["Lackmeyer reports on planned Chevy Bricktown Events Center renovations aimed at attracting performers. The venue remains part of the family’s entertainment story. The Oklahoman ↗"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "The Oklahoman ↗", "href": "https://www.oklahoman.com/story/business/columns/steve-lackmeyer/2014/04/28/chevy-bricktown-events-center-to-undergo-renovation-aimed-at-attracting-performers/60828351007/"}]}, {"id": "reggae-fest-becomes-a-tradition", "title": "Reggae Fest becomes a tradition", "date_label": "2014", "sort_order": 21, "era": "THE FAMILY CARRIES IT FORWARD", "paragraphs": ["The Journal Record reports that Brewer Entertainment has hosted Reggae Fest for 19 years. The free festival brings performers and crowds together, alongside the practical challenges of producing outdoor events. [9]"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[9]", "href": "#source-9"}]}, {"id": "renovating-in-jims-honor", "title": "Renovating in Jim’s honor", "date_label": "2015", "sort_order": 22, "era": "THE FAMILY CARRIES IT FORWARD", "paragraphs": ["The Journal Record covers Brent and Brett’s plans to bring new life to the former Haunted Warehouse buildings as a tribute to their father. The Journal Record ↗"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "The Journal Record ↗", "href": "https://journalrecord.com/2015/04/08/new-life-for-haunted-house-site-brewer-brothers-to-reanimate-buildings-as-tribute-to-bricktown-pioneer-real-estate/"}]}, {"id": "a-new-landmark-on-a-familiar-wall", "title": "A new landmark on a familiar wall", "date_label": "2016", "sort_order": 23, "era": "THE FAMILY CARRIES IT FORWARD", "paragraphs": ["Jack Fowler’s Bricktown Okctopus mural takes shape on the event-center wall. The large artwork becomes another recognizable part of the district. [14]"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "[14]", "href": "#source-14"}]}, {"id": "new-events-a-continuing-tradition", "title": "New events. A continuing tradition.", "date_label": "2019", "sort_order": 24, "era": "THE FAMILY CARRIES IT FORWARD", "paragraphs": ["Lackmeyer’s Bricktown Throwdown coverage connects the athletic competition to Brett and Brent’s event business and the district’s tradition of bringing people together. The Oklahoman ↗"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "The Oklahoman ↗", "href": "https://www.oklahoman.com/story/business/columns/steve-lackmeyer/2019/06/11/bricktown-throwdown-continues-tradition/60451089007/"}]}, {"id": "the-sons-carry-the-story-forward", "title": "The sons carry the story forward", "date_label": "2019", "sort_order": 25, "era": "THE FAMILY CARRIES IT FORWARD", "paragraphs": ["A November Lackmeyer feature follows Brent and Brett continuing to develop and invest in the places associated with their father’s legacy. The Oklahoman ↗"], "evidence_note": "Published sources and identified family recollections", "full_width": false, "status": "published", "reference_links": [{"label": "The Oklahoman ↗", "href": "https://www.oklahoman.com/story/business/columns/steve-lackmeyer/2019/11/05/sons-continue-evolution-of-late-fathers-legacy/60423478007/"}]}, {"id": "thirty-years-of-st-patricks-day", "title": "Thirty years of St. Patrick’s Day", "date_label": "2020", "sort_order": 26, "era": "THE FAMILY CARRIES IT FORWARD", "paragraphs": ["A Gazette interview recalls O’Brien’s 1990 opening and three decades of block parties. Brent describes the brothers’ continuing work and plans to dedicate that year’s celebration to Jim. [4]"], "evidence_note": "Published sources and identified family recollections", "full_width": true, "status": "published", "reference_links": [{"label": "[4]", "href": "#source-4"}]}]'::jsonb) on conflict (id) do nothing;
