, "status": "published"}, {"id": "article-10", "title": "Jim and Patsy Brewer parking-lot sale", "publisher": "The Journal Record", "author": "", "date_label": "2004-12-10", "date_sort": "2004-12-10", "source_url": "https://journalrecord.com/2004/12/10/major-land-sales-mansions-north-apartments-sell-for-407-million/", "categories": ["business"], "article_type": "Transaction report", "summary": "A property-transactions roundup reports Jim and Patsy Brewer selling a parking lot near Sheridan and Joe Carter for a proposed Bricktown Market Place development. The apartment sale in the original headline is a separate transaction.", "source_note": "", "evidence": "", "metadata": {"id": "article-10", "date": "2004-12-10", "title": "Jim and Patsy Brewer parking-lot sale", "publisher": "The Journal Record", "categories": ["business"], "type": "Transaction report", "url": "https://journalrecord.com/2004/12/10/major-land-sales-mansions-north-apartments-sell-for-407-million/", "summary": "A property-transactions roundup reports Jim and Patsy Brewer selling a parking lot near Sheridan and Joe Carter for a proposed Bricktown Market Place development. The apartment sale in the original headline is a separate transaction.", "context": "", "status": "published"}, "status": "published"}, {"id": "article-11", "title": "Celebrate the Fourth at Red, White and Boom!", "publisher": "Oklahoma Gazette", "author": "", "date_label": "2007-06-28", "date_sort": "2007-06-28", "source_url": "https://www.okgazette.com/news/celebrate-the-fourth-at-red-white-and-boom-festival-2947363/", "categories": ["festivals"], "article_type": "Festival preview", "summary": "C.J. Macklin previews Brewer Entertainment’s free, three-day celebration with the Oklahoma City Philharmonic and other performers. This event was at Downtown Airpark, separate from Bricktown’s earlier fireworks celebrations.", "source_note": "", "evidence": "", "metadata": {"id": "article-11", "date": "2007-06-28", "title": "Celebrate the Fou